import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { Trip } from '../../models/trip';
import { TripService } from '../../services/trip.service';

@Component({
  selector: 'app-trip-add',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './trip-add.component.html',
  styleUrls: ['./trip-add.component.css']
})
export class TripAddComponent {
  trip: Trip = {
    code: '',
    name: '',
    length: '',
    start: '',
    resort: '',
    perPerson: '',
    image: '',
    description: ''
  };

  loading = false;
  error: string | null = null;
  success: string | null = null;

  constructor(
    private tripService: TripService,
    private router: Router
  ) {}

  onSubmit(): void {
    if (!this.validateForm()) {
      return;
    }

    this.loading = true;
    this.error = null;
    this.success = null;

    this.tripService.createTrip(this.trip).subscribe({
      next: (response) => {
        this.loading = false;
        this.success = 'Trip created successfully!';

        // Redirect to trips list after a short delay
        setTimeout(() => {
          this.router.navigate(['/trips']);
        }, 1500);
      },
      error: (error) => {
        this.loading = false;
        this.error = error.message || 'Failed to create trip. Please try again.';
        console.error('Error creating trip:', error);
      }
    });
  }

  validateForm(): boolean {
    if (!this.trip.code?.trim()) {
      this.error = 'Trip code is required';
      return false;
    }
    if (!this.trip.name?.trim()) {
      this.error = 'Trip name is required';
      return false;
    }
    if (!this.trip.length?.trim()) {
      this.error = 'Trip length is required';
      return false;
    }
    if (!this.trip.start?.trim()) {
      this.error = 'Start date is required';
      return false;
    }
    if (!this.trip.resort?.trim()) {
      this.error = 'Resort information is required';
      return false;
    }
    if (!this.trip.perPerson?.trim()) {
      this.error = 'Price per person is required';
      return false;
    }
    if (!this.trip.image?.trim()) {
      this.error = 'Image URL is required';
      return false;
    }
    if (!this.trip.description?.trim()) {
      this.error = 'Description is required';
      return false;
    }

    this.error = null;
    return true;
  }

  onCancel(): void {
    this.router.navigate(['/trips']);
  }

  clearForm(): void {
    this.trip = {
      code: '',
      name: '',
      length: '',
      start: '',
      resort: '',
      perPerson: '',
      image: '',
      description: ''
    };
    this.error = null;
    this.success = null;
  }

  formatCode(): void {
    if (this.trip.code) {
      this.trip.code = this.trip.code.toUpperCase().replace(/[^A-Z0-9]/g, '');
    }
  }

  formatPrice(): void {
    if (this.trip.perPerson) {
      // Remove any non-numeric characters except decimal point
      let price = this.trip.perPerson.replace(/[^0-9.]/g, '');

      // Ensure only one decimal point
      const parts = price.split('.');
      if (parts.length > 2) {
        price = parts[0] + '.' + parts.slice(1).join('');
      }

      // Add dollar sign and formatting
      if (price && !isNaN(parseFloat(price))) {
        const numericPrice = parseFloat(price);
        this.trip.perPerson = `$${numericPrice.toLocaleString('en-US', {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2
        })}`;
      }
    }
  }
}

<div class="container mt-4">
  <div class="row justify-content-center">
    <div class="col-lg-8 col-md-10">
      <!-- Header -->
      <div class="card shadow-sm border-0 mb-4">
        <div class="card-header bg-primary text-white">
          <h2 class="mb-0">
            <i class="fas fa-plus-circle me-2"></i>Add New Trip
          </h2>
          <p class="mb-0 mt-1 opacity-75">Create a new travel package</p>
        </div>
      </div>

      <!-- Success Message -->
      <div *ngIf="success" class="alert alert-success alert-dismissible fade show" role="alert">
        <i class="fas fa-check-circle me-2"></i>{{ success }}
        <button type="button" class="btn-close" (click)="success = null"></button>
      </div>

      <!-- Error Message -->
      <div *ngIf="error" class="alert alert-danger alert-dismissible fade show" role="alert">
        <i class="fas fa-exclamation-triangle me-2"></i>{{ error }}
        <button type="button" class="btn-close" (click)="error = null"></button>
      </div>

      <!-- Add Trip Form -->
      <div class="card shadow-sm border-0">
        <div class="card-body p-4">
          <form (ngSubmit)="onSubmit()" #tripForm="ngForm" novalidate>
            <div class="row">
              <!-- Trip Code -->
              <div class="col-md-6 mb-3">
                <label for="code" class="form-label fw-semibold">
                  <i class="fas fa-barcode me-1"></i>Trip Code *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="code"
                  name="code"
                  [(ngModel)]="trip.code"
                  (blur)="formatCode()"
                  placeholder="e.g., GALR210214"
                  maxlength="20"
                  required>
                <div class="form-text">Unique identifier for the trip (letters and numbers only)</div>
              </div>

              <!-- Trip Name -->
              <div class="col-md-6 mb-3">
                <label for="name" class="form-label fw-semibold">
                  <i class="fas fa-map-marked-alt me-1"></i>Trip Name *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="name"
                  name="name"
                  [(ngModel)]="trip.name"
                  placeholder="e.g., Gale Reef Adventure"
                  maxlength="100"
                  required>
              </div>
            </div>

            <div class="row">
              <!-- Length -->
              <div class="col-md-6 mb-3">
                <label for="length" class="form-label fw-semibold">
                  <i class="fas fa-calendar-alt me-1"></i>Duration *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="length"
                  name="length"
                  [(ngModel)]="trip.length"
                  placeholder="e.g., 4 days / 3 nights"
                  maxlength="50"
                  required>
              </div>

              <!-- Start Date -->
              <div class="col-md-6 mb-3">
                <label for="start" class="form-label fw-semibold">
                  <i class="fas fa-calendar-check me-1"></i>Start Date *
                </label>
                <input
                  type="date"
                  class="form-control"
                  id="start"
                  name="start"
                  [(ngModel)]="trip.start"
                  required>
              </div>
            </div>

            <div class="row">
              <!-- Resort -->
              <div class="col-md-6 mb-3">
                <label for="resort" class="form-label fw-semibold">
                  <i class="fas fa-hotel me-1"></i>Resort/Accommodation *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="resort"
                  name="resort"
                  [(ngModel)]="trip.resort"
                  placeholder="e.g., Emerald Bay, 3 stars"
                  maxlength="100"
                  required>
              </div>

              <!-- Price Per Person -->
              <div class="col-md-6 mb-3">
                <label for="perPerson" class="form-label fw-semibold">
                  <i class="fas fa-dollar-sign me-1"></i>Price Per Person *
                </label>
                <input
                  type="text"
                  class="form-control"
                  id="perPerson"
                  name="perPerson"
                  [(ngModel)]="trip.perPerson"
                  (blur)="formatPrice()"
                  placeholder="e.g., $1,269.00"
                  maxlength="20"
                  required>
              </div>
            </div>

            <!-- Image URL -->
            <div class="mb-3">
              <label for="image" class="form-label fw-semibold">
                <i class="fas fa-image me-1"></i>Image URL *
              </label>
              <input
                type="url"
                class="form-control"
                id="image"
                name="image"
                [(ngModel)]="trip.image"
                placeholder="https://example.com/image.jpg"
                required>
              <div class="form-text">URL to the trip's main image</div>
            </div>

            <!-- Description -->
            <div class="mb-4">
              <label for="description" class="form-label fw-semibold">
                <i class="fas fa-align-left me-1"></i>Description *
              </label>
              <textarea
                class="form-control"
                id="description"
                name="description"
                [(ngModel)]="trip.description"
                rows="4"
                placeholder="Describe the trip experience, activities, and highlights..."
                maxlength="1000"
                required></textarea>
              <div class="form-text">{{ trip.description?.length || 0 }}/1000 characters</div>
            </div>

            <!-- Form Actions -->
            <div class="d-flex gap-3 justify-content-end">
              <button
                type="button"
                class="btn btn-outline-secondary"
                (click)="onCancel()"
                [disabled]="loading">
                <i class="fas fa-times me-2"></i>Cancel
              </button>

              <button
                type="button"
                class="btn btn-outline-warning"
                (click)="clearForm()"
                [disabled]="loading">
                <i class="fas fa-eraser me-2"></i>Clear Form
              </button>

              <button
                type="submit"
                class="btn btn-success"
                [disabled]="loading || !tripForm.form.valid">
                <span *ngIf="loading" class="spinner-border spinner-border-sm me-2"></span>
                <i *ngIf="!loading" class="fas fa-save me-2"></i>
                {{ loading ? 'Creating...' : 'Create Trip' }}
              </button>
            </div>
          </form>
        </div>
      </div>

      <!-- Form Help -->
      <div class="card bg-light border-0 mt-4">
        <div class="card-body">
          <h6 class="card-title">
            <i class="fas fa-info-circle me-2"></i>Form Guidelines
          </h6>
          <ul class="mb-0 small">
            <li>All fields marked with * are required</li>
            <li>Trip codes should be unique and contain only letters and numbers</li>
            <li>Use clear, descriptive names for better searchability</li>
            <li>Include star ratings in resort information (e.g., "Resort Name, 4 stars")</li>
            <li>Prices will be automatically formatted with currency symbols</li>
            <li>Provide high-quality image URLs for better presentation</li>
          </ul>
        </div>
      </div>
    </div>
  </div>
</div>
